'use strict';
const $=s=>document.querySelector(s);const KEY='cap-terminal-v1';let state={quests:[],notes:[],effects:true};let filter='active',editing=null,kind='quest';
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.quests)&&Array.isArray(s.notes))state=s;}catch{setTimeout(()=>toast('Не удалось прочитать данные. Можно восстановить копию в системе.'),100)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Не удалось сохранить: проверь доступное место и настройки браузера.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function node(tag,text,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n}
function button(text,fn,cls='minor'){const n=node('button',text,cls);n.onclick=fn;return n}
function xp(){return state.quests.filter(q=>q.done).reduce((n,q)=>n+q.xp,0)}
function render(){const total=xp(),level=Math.floor(total/100)+1,done=state.quests.filter(q=>q.done).length;$('#level').textContent=String(level).padStart(2,'0');$('#xp').textContent=`${total%100} / 100 XP`;$('#xpbar').style.width=(total%100)+'%';$('#rank').textContent=level<3?'НОВЫЙ ЖИТЕЛЬ':level<6?'ИССЛЕДОВАТЕЛЬ':'ЛЕГЕНДА ПУСТОШИ';$('#statRank').textContent=`Уровень ${level} / ${$('#rank').textContent}`;$('#statText').textContent=`Завершено квестов: ${done}. Всего опыта: ${total} XP.`;$('#activeCount').textContent=state.quests.length-done;$('#doneCount').textContent=done;$('#totalXp').textContent=total;document.body.classList.toggle('crt',state.effects);$('#effects').checked=state.effects;const list=$('#questList');list.replaceChildren();const rows=state.quests.filter(q=>filter==='all'||q.done===(filter==='done'));$('#questCount').textContent=String(rows.length).padStart(2,'0');if(!rows.length)list.append(node('div',filter==='done'?'Здесь будут твои победы. Первая уже на подходе.':'Сигнал чист. Квестов нет.\nДобавь первое дело — например, «Прогуляться 20 минут».','empty'));rows.forEach(q=>{const row=node('article','','quest'+(q.done?' done':''));const check=button(q.done?'✓':'',()=>{q.done=!q.done;persist();render();toast(q.done?`Квест выполнен. +${q.xp} XP`:'Квест снова активен')},'check');check.setAttribute('aria-label',q.done?'Вернуть квест: '+q.title:'Завершить квест: '+q.title);check.setAttribute('aria-pressed',String(q.done));const body=node('div','','quest-body');body.append(node('h3',q.title));if(q.description)body.append(node('p',q.description));body.append(node('span',q.done?'МИССИЯ ЗАВЕРШЕНА':'АКТИВНАЯ МИССИЯ','tag'));body.append(button('Изменить',()=>openEditor('quest',q)),button('Удалить',()=>{if(confirm('Удалить квест? Его опыт тоже будет удалён.')){state.quests=state.quests.filter(x=>x.id!==q.id);persist();render()}}));row.append(check,body,node('span',`+${q.xp} XP`,'reward'));list.append(row)});const notes=$('#noteList');notes.replaceChildren();if(!state.notes.length)notes.append(node('div','Пока ни одной записи. Здесь можно хранить идеи, планы и координаты тайника с печеньем.','empty'));state.notes.forEach(n=>{const card=node('article','','note');card.append(node('time',new Date(n.updated).toLocaleDateString('ru-RU')),node('h2',n.title),node('p',n.description),button('Изменить',()=>openEditor('note',n)),button('Удалить',()=>{if(confirm('Удалить запись?')){state.notes=state.notes.filter(x=>x.id!==n.id);persist();render()}}));notes.append(card)})}
function openEditor(type,item){kind=type;editing=item?.id||null;$('#editorForm').reset();$('#editorLabel').textContent=type==='quest'?'НОВАЯ МИССИЯ':'ПОЛЕВАЯ ЗАПИСЬ';$('#editorTitle').textContent=item?'Редактирование':type==='quest'?'Добавить квест':'Добавить запись';$('#title').value=item?.title||'';$('#description').value=item?.description||'';$('#difficulty').value=item?.xp||25;$('#difficultyLabel').hidden=type!=='quest';$('#editor').showModal();$('#title').focus()}
$('#editorForm').onsubmit=e=>{e.preventDefault();const title=$('#title').value.trim();if(!title){$('#title').setCustomValidity('Введи название');$('#title').reportValidity();return}const arr=kind==='quest'?state.quests:state.notes;const old=arr.find(x=>x.id===editing);const data={id:editing||(crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('')),title,description:$('#description').value.trim(),updated:new Date().toISOString()};if(kind==='quest'){data.xp=Number($('#difficulty').value);data.done=old?.done||false}if(old)Object.assign(old,data);else arr.unshift(data);persist();render();$('#editor').close();toast('Сохранено в терминале')};$('#title').oninput=()=>$('#title').setCustomValidity('');$('#cancel').onclick=()=>$('#editor').close();$('#newQuest').onclick=()=>openEditor('quest');$('#newNote').onclick=()=>openEditor('note');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==b.dataset.tab);document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n===b))});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(n=>n.classList.toggle('active',n===b));render()});$('#effects').onchange=e=>{state.effects=e.target.checked;persist();render()};$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='cap-terminal-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error();const s=JSON.parse(await file.text());if(s.version!==1||!Array.isArray(s.quests)||!Array.isArray(s.notes)||typeof s.effects!=='boolean')throw Error();for(const [arr,isQuest] of [[s.quests,true],[s.notes,false]]){const ids=new Set();for(const x of arr){if(typeof x.id!=='string'||ids.has(x.id)||typeof x.title!=='string'||!x.title.trim()||x.title.length>120||typeof x.description!=='string'||x.description.length>5000||!Number.isFinite(Date.parse(x.updated))||(isQuest&&(![10,25,50].includes(x.xp)||typeof x.done!=='boolean')))throw Error();ids.add(x.id)}}if(confirm('Заменить текущие данные резервной копией?')){state={quests:s.quests,notes:s.notes,effects:s.effects};persist();render();toast('Копия восстановлена')}}catch{toast('Не удалось прочитать копию: неверный формат файла.')}e.target.value=''};
function network(){$('#network').textContent=navigator.onLine?'● СИСТЕМА АКТИВНА':'● АВТОНОМНЫЙ РЕЖИМ'}window.addEventListener('online',network);window.addEventListener('offline',network);function clock(){$('#clock').textContent=new Date().toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}clock();setInterval(clock,30000);network();render();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>$('#offline').textContent='Офлайн-кэш подготовлен. Квесты и журнал доступны без сети после успешной первой загрузки. На хостинге вход в аккаунт иногда может потребовать интернет.').catch(()=>$('#offline').textContent='Офлайн-кэш недоступен. Пока открывай приложение с интернетом.')}else $('#offline').textContent='Этот браузер не поддерживает офлайн-кэш.';
